using System;using System.IO;using System.Reflection;
class ExtractMenuIcons {static void Main(string[] args){var assembly=Assembly.LoadFile(Path.GetFullPath(args[0]));string[] names={"settings","prev-circle","logo","edit-circle","beatmap","player","online","tournament","skin-b"};foreach(string icon in names){string found=null;foreach(string resource in assembly.GetManifestResourceNames())if(resource.EndsWith(".Icons."+(icon=="edit-circle"?"EditCircle":icon)+".png",StringComparison.OrdinalIgnoreCase)){found=resource;break;}if(found==null)throw new Exception("Missing upstream icon "+icon);using(var input=assembly.GetManifestResourceStream(found))using(var output=File.Create(Path.Combine(args[1],"menu-icon-"+icon+".png")))input.CopyTo(output);Console.WriteLine(found);}}}
